import React, { useState, useEffect } from "react";
import "./App.css";
import * as XLSX from "xlsx";
import { saveAs } from "file-saver";

// ✅ Firebase imports
import { db } from "./firebase";
import {
  collection,
  addDoc,
  updateDoc,
  deleteDoc,
  doc,
  onSnapshot
} from "firebase/firestore";

function App() {
  const employeesCollection = collection(db, "employees");

  const [employees, setEmployees] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [editingId, setEditingId] = useState(null);

  const [formData, setFormData] = useState({
    lastName: "",
    firstName: "",
    middleInitial: "",
    dateOfBirth: "",
    sex: "",
    csEligibility: "",
    workStatus: "",
    yearsAsJO: "",
    office: "",
    designation: "",
    natureOfWork: "",
    pwd: "",
    indigenous: "",
    soloParentId: "",
    landbankAccount: "",
    tin: ""
  });

  // Filters
  const [searchTerm, setSearchTerm] = useState("");
  const [filterStatus, setFilterStatus] = useState("all");
  const [filterOffice, setFilterOffice] = useState("all");

  // Cancel Modal
  const [showCancelModal, setShowCancelModal] = useState(false);
  const [cancelTargetId, setCancelTargetId] = useState(null);
  const [cancelDate, setCancelDate] = useState("");

  useEffect(() => {
    const unsubscribe = onSnapshot(employeesCollection, (snapshot) => {
      setEmployees(snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() })));
    });
    return () => unsubscribe();
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSave = async () => {
    try {
      if (editingId) {
        const empRef = doc(db, "employees", editingId);
        await updateDoc(empRef, formData);
        setEditingId(null);
      } else {
        await addDoc(employeesCollection, { ...formData, cancelled: false });
      }

      setFormData({
        lastName: "",
        firstName: "",
        middleInitial: "",
        dateOfBirth: "",
        sex: "",
        csEligibility: "",
        workStatus: "",
        yearsAsJO: "",
        office: "",
        designation: "",
        natureOfWork: "",
        pwd: "",
        indigenous: "",
        soloParentId: "",
        landbankAccount: "",
        tin: ""
      });
      setShowModal(false);
    } catch (err) {
      console.error("Error saving employee:", err);
    }
  };

  const handleEdit = (employee) => {
    setFormData(employee);
    setEditingId(employee.id);
    setShowModal(true);
  };

  // 🟠 Show cancel popup
  const openCancelModal = (id) => {
    setCancelTargetId(id);
    setCancelDate(new Date().toISOString().split("T")[0]); // default today
    setShowCancelModal(true);
  };

  // ✅ Confirm cancel with date
  const confirmCancel = async () => {
    try {
      const empRef = doc(db, "employees", cancelTargetId);
      await updateDoc(empRef, {
        cancelled: true,
        cancelledDate: cancelDate
      });
      setShowCancelModal(false);
      setCancelTargetId(null);
      setCancelDate("");
    } catch (err) {
      console.error("Error cancelling employee:", err);
    }
  };

  // ↩️ Undo cancel
  const handleUndoCancel = async (id) => {
    try {
      const empRef = doc(db, "employees", id);
      await updateDoc(empRef, {
        cancelled: false,
        cancelledDate: null
      });
    } catch (err) {
      console.error("Error undoing cancel:", err);
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm("Are you sure you want to delete this employee?")) {
      try {
        const empRef = doc(db, "employees", id);
        await deleteDoc(empRef);
      } catch (err) {
        console.error("Error deleting employee:", err);
      }
    }
  };

  const handleDownloadExcel = () => {
    if (employees.length === 0) {
      alert("No data to download!");
      return;
    }
    const exportData = employees.map(({ id, ...rest }) => rest);
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Employees");

    const excelBuffer = XLSX.write(workbook, { bookType: "xlsx", type: "array" });
    const data = new Blob([excelBuffer], { type: "application/octet-stream" });
    saveAs(data, "Employee_List.xlsx");
  };

  const clearAllFilters = () => {
    setSearchTerm("");
    setFilterStatus("all");
    setFilterOffice("all");
  };

  const officeList = [
    "all",
    ...Array.from(new Set(employees.map((emp) => emp.office || ""))).filter(
      (o) => o !== ""
    )
  ];

  const filteredEmployees = employees.filter((emp) => {
    const matchesSearch =
      `${emp.lastName} ${emp.firstName} ${emp.middleInitial} ${emp.office} ${emp.designation}`
        .toLowerCase()
        .includes(searchTerm.toLowerCase());

    const matchesStatus =
      filterStatus === "all"
        ? true
        : filterStatus === "cancelled"
        ? emp.cancelled
        : !emp.cancelled;

    const matchesOffice =
      filterOffice === "all" ? true : emp.office === filterOffice;

    return matchesSearch && matchesStatus && matchesOffice;
  });

  return (
    <div className="App">
      <h1>Employee Information System</h1>

      {/* Search & Filter Bar */}
      <div className="search-filter-bar">
        <input
          type="text"
          placeholder="🔍 Search by name, office, or designation..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />

        <select
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
        >
          <option value="all">All Status</option>
          <option value="active">Active</option>
          <option value="cancelled">Cancelled</option>
        </select>

        <select
          value={filterOffice}
          onChange={(e) => setFilterOffice(e.target.value)}
        >
          {officeList.map((office) => (
            <option key={office} value={office}>
              {office === "all" ? "All Offices" : office}
            </option>
          ))}
        </select>

        <button className="clear-filters-btn" onClick={clearAllFilters}>
          Clear Filters
        </button>
      </div>

      {/* Buttons */}
      <div className="button-bar">
        <button className="add-btn" onClick={() => setShowModal(true)}>
          ➕ Add Employee
        </button>
        <button className="download-btn" onClick={handleDownloadExcel}>
          📥 Download Excel
        </button>
      </div>

      {/* Table */}
      <table>
       <thead>
  <tr>
    <th rowSpan="2">No.</th>
    <th colSpan="3">Name of Personnel</th>
    <th rowSpan="2">Date of Birth<br />(YYYY-MM-DD)</th>
    <th rowSpan="2" className="narrow-col">Sex<br />(pls. select)</th>
    <th rowSpan="2">Level of CS Eligibility<br />(pls. select)</th>
    <th rowSpan="2" className="narrow-col">Work Status<br />(pls. select)</th>
    <th rowSpan="2" className="narrow-col">No. of Years of Service<br />as JO/COS/MOA personnel</th>
    <th rowSpan="2">Designation / Position</th>
    <th rowSpan="2">Nature of Work<br />Please Specify</th>
    <th rowSpan="2">Office</th>
    <th rowSpan="2" className="narrow-col">PWD (Y)</th>
    <th rowSpan="2" className="narrow-col">Indigenous People (Y)</th>
    <th rowSpan="2">Solo Parent<br />(ID Number)</th>
    <th rowSpan="2">Landbank Savings/PISO Account Number<br />(***********)</th>
    <th rowSpan="2">TIN Number</th>
    <th rowSpan="2">Actions</th>
  </tr>
  <tr>
    <th>Surname</th>
    <th>First Name / Extension Name</th>
    <th>Middle Initial</th>
  </tr>
</thead>
        <tbody>
          {filteredEmployees.map((emp, index) => (
            <tr key={emp.id} className={emp.cancelled ? "cancelled-row" : ""}>
              <td>{index + 1}</td>
              <td>{emp.lastName}</td>
              <td>{emp.firstName}</td>
              <td>{emp.middleInitial}</td>
              <td>{emp.dateOfBirth}</td>
              <td>{emp.sex}</td>
              <td>{emp.csEligibility}</td>
              <td>{emp.workStatus}</td>
              <td>{emp.yearsAsJO}</td>
              <td>{emp.office}</td>
              <td>{emp.designation}</td>
              <td>{emp.natureOfWork}</td>
              <td>{emp.pwd}</td>
              <td>{emp.indigenous}</td>
              <td>{emp.soloParentId}</td>
              <td>{emp.landbankAccount}</td>
              <td>{emp.tin}</td>
              <td>{emp.cancelledDate || ""}</td>
              <td>
                {emp.cancelled ? (
                  <button
                    className="cancel-btn"
                    onClick={() => handleUndoCancel(emp.id)}
                  >
                    ↩️ Undo
                  </button>
                ) : (
                  <button
                    className="cancel-btn"
                    onClick={() => openCancelModal(emp.id)}
                  >
                    ❌ Cancel
                  </button>
                )}
                <button className="edit-btn" onClick={() => handleEdit(emp)}>
                  ✏️
                </button>
                <button className="delete-btn" onClick={() => handleDelete(emp.id)}>
                  🗑️
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* Add/Edit Modal */}
      {showModal && (
        <div className="modal-overlay">
          <div className="modal">
            <h2>{editingId ? "Edit Employee" : "Add New Employee"}</h2>
            <div className="form-grid">
              {Object.keys(formData).map((key) => (
                <div className="form-group" key={key}>
                  <label>{key}</label>
                  <input
                    type="text"
                    name={key}
                    value={formData[key]}
                    onChange={handleChange}
                  />
                </div>
              ))}
            </div>
            <div className="modal-actions">
              <button onClick={handleSave}>
                {editingId ? "Update" : "Save"}
              </button>
              <button
                onClick={() => {
                  setShowModal(false);
                  setEditingId(null);
                }}
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Cancel Date Modal */}
      {showCancelModal && (
        <div className="modal-overlay">
          <div className="modal">
            <h3>Cancel Employee</h3>
            <p>Please select the date of cancellation:</p>
            <input
              type="date"
              value={cancelDate}
              onChange={(e) => setCancelDate(e.target.value)}
            />
            <div className="modal-actions">
              <button onClick={confirmCancel}>Confirm</button>
              <button onClick={() => setShowCancelModal(false)}>Close</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
